    static func readSliceCoordinate(_ r: inout AsukaNativeReader) -> [Coordinate] {
        let n = r.len()
        var v: [Coordinate] = []
        v.reserveCapacity(n)
        for _ in 0..<n { v.append(Wire.readCoordinate(&r)) }
        return v
    }

